import React, { useEffect, useState } from "react";
import { Button, Container, IconButton } from "@mui/material";
import { ThemeProvider } from "@mui/material/styles";
import DarkModeIcon from "@mui/icons-material/DarkMode";
import LightModeIcon from "@mui/icons-material/LightMode";

import axios from "axios";
import AuthForm from "./components/AuthForm";
import EventForm from "./components/EventForm";
import EventList from "./components/EventList";
import { initAuth, setAuthToken } from "./auth";
import { getTheme } from "./theme";

const API = "http://localhost:5500/api/events";

function App() {
  const [user, setUser] = useState(null);
  const [events, setEvents] = useState([]);
  const [editingEvent, setEditingEvent] = useState(null);
  const [themeMode, setThemeMode] = useState("dark"); // DARK MODE by default

  const fetchEvents = async () => {
    try {
      const { data } = await axios.get(API);
      setEvents(data);
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    const token = initAuth();
    if (token) setUser({});
    fetchEvents();
  }, []);

  const handleLogout = () => {
    setAuthToken(null);
    setUser(null);
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`${API}/${id}`);
      fetchEvents();
    } catch (err) {
      console.error(err);
    }
  };

  const handleEdit = (event) => {
    setEditingEvent(event);
  };

  if (!user) {
    return <AuthForm onSuccess={(usr) => setUser(usr)} />;
  }

  return (
    <ThemeProvider theme={getTheme(themeMode)}>
      <Container sx={{ mt: 4 }}>

        {/* 🌙 DARK MODE TOGGLE */}
        <IconButton
          onClick={() =>
            setThemeMode(themeMode === "light" ? "dark" : "light")
          }
          sx={{ float: "right" }}
        >
          {themeMode === "dark" ? <LightModeIcon /> : <DarkModeIcon />}
        </IconButton>

        <Button variant="outlined" onClick={handleLogout}>
          Logout
        </Button>

        <EventForm
          onEventAdded={fetchEvents}
          editingEvent={editingEvent}
          clearEditing={() => setEditingEvent(null)}
        />

        <EventList
          events={events}
          onDelete={handleDelete}
          onEdit={handleEdit}
        />
      </Container>
    </ThemeProvider>
  );
}

export default App;
